<template><div class="office-page"><AppSidebar/><main class="office-main"><header class="page-header"><div><h2>通知中心</h2><p>会议邀请、行动项、审批流转和风险提醒</p></div><el-badge :value="unread" :hidden="!unread"><el-button @click="load">刷新</el-button></el-badge></header><el-empty v-if="!items.length" description="暂无通知"/><el-card v-for="item in items" :key="item.id" class="notice" :class="{unread:!item.is_read}" @click.native="read(item)"><div><strong>{{item.title}}</strong><p>{{item.content}}</p><small>{{item.created_at}}</small></div><el-tag size="mini" :type="item.is_read?'info':'primary'">{{item.is_read?'已读':'未读'}}</el-tag></el-card></main></div></template>
<script>import AppSidebar from '../components/Sidebar/index.vue';export default{components:{AppSidebar},computed:{workspace(){return this.$store.getters['workspace/activeWorkspace']||{}},items(){return this.$store.state.office.notifications},unread(){return this.$store.state.office.unreadNotifications}},watch:{'workspace.id':{immediate:true,handler(){this.load()}}},methods:{load(){if(this.workspace.id&&this.workspace.domain==='office')return this.$store.dispatch('office/loadNotifications',this.workspace.id)},read(item){if(!item.is_read)this.$store.dispatch('office/readNotification',{id:item.id,workspaceId:this.workspace.id})}}}</script><style scoped>.office-page{display:flex;height:100vh;box-sizing:border-box;overflow:hidden;padding:12px;gap:12px;background:#f5f7fb}.office-main{flex:1;min-width:0;overflow-y:auto;padding:24px;background:#fff;border-radius:12px}.page-header{display:flex;justify-content:space-between;border-bottom:1px solid #edf0f5;padding-bottom:15px;margin-bottom:18px}.page-header h2{margin:0 0 6px}.page-header p{margin:0;color:#7b8794}.notice{margin-bottom:10px;cursor:pointer}.notice.unread{border-left:4px solid #409eff}.notice>div{display:flex;justify-content:space-between}.notice p{margin:8px 0;color:#4b5563}.notice small{color:#909399}</style>
